// send yet" and "a follow-up is already waiting for you" are the same check and neither one drafts
// anything new. Once you press send, Gmail turns that draft into a message with the SENT label.
const prospects = $('Is There A Thread To Check?').all().map((i) => i.json);

const labelsOf = (message) => (message.labels || []).map((l) => String(l.id || '').toUpperCase());
const headerOf = (message, name) => String(message[name] || '');

return $input.all().map((item, index) => {
  const p = prospects[index];
  if (!p) return { json: { skipped: true } };

  const thread = item.json || {};
  const messages = Array.isArray(thread.messages) ? thread.messages : [];
  const decided = (state, extra) => ({ json: Object.assign({}, p, { thread_state: state, followup_due: state === 'due', messages_in_thread: messages.length }, extra || {}) });

  if (messages.length === 0) return decided('unreadable', { reject_reason: 'the stored thread returned no messages' });

  const hasDraft = messages.some((m) => labelsOf(m).indexOf('DRAFT') !== -1);
  if (hasDraft) return decided('draft_waiting');

  const sentMessages = messages.filter((m) => labelsOf(m).indexOf('SENT') !== -1);
  if (sentMessages.length === 0) return decided('not_sent');

  const inbound = messages.filter((m) => labelsOf(m).indexOf('SENT') === -1 && headerOf(m, 'From'));
  if (inbound.length > 0) {
    return decided('replied', {
      status: 'replied',
      sequence_state: 'inactive',
      replied_at: new Date(Number(inbound[inbound.length - 1].internalDate || Date.now())).toISOString(),
    });
  }

  const lastSent = sentMessages.reduce((max, m) => Math.max(max, Number(m.internalDate || 0)), 0);
  const sentAt = lastSent ? new Date(lastSent).toISOString() : new Date().toISOString();
  const drafted = Number(p.followups_drafted || 0);

  if (drafted >= p.max_followups) {
    return decided('sequence_complete', { status: 'sequence_complete', sequence_state: 'inactive', sent_detected_at: p.sent_detected_at || sentAt });
  }

  const gapMs = p.followup_gap_days * 86400000;
  if (lastSent && Date.now() - lastSent < gapMs) {
    return decided('waiting', { status: 'sent_by_human', sent_detected_at: p.sent_detected_at || sentAt, next_followup_at: new Date(lastSent + gapMs).toISOString() });
  }

  return decided('due', { status: 'sent_by_human', sent_detected_at: p.sent_detected_at || sentAt, last_sent_at: sentAt });
});

