// answer (200 found:false, charged) from a failure (>=400) instead of guessing from an error item.
function httpStatus(item) { const j = item && item.json ? item.json : item; return Number(j && j.statusCode) || 0; }
function httpBody(item) { const j = item && item.json ? item.json : item; return (j && j.body) || {}; }
function httpOk(item) { const s = httpStatus(item); return s >= 200 && s < 300; }
function httpCost(item) { return httpOk(item) ? Number(httpBody(item).costUsd || 0) : 0; }
function httpFound(item) { const o = httpBody(item).output || {}; return o.found === true; }
function httpData(item) { const o = httpBody(item).output || {}; return o.data || null; }
function httpErrorCode(item) {
  const b = httpBody(item);
  const e = b && b.error;
  if (e && typeof e === 'object') return String(e.code || e.message || 'error');
  if (typeof b === 'string') return b.slice(0, 200);
  return String((b && b.code) || httpStatus(item) || 'error');
}

const prospects = $('Build The Follow-Up Draft').all().map((i) => i.json);

return $input.all().map((item, index) => {
  const p = prospects[index];
  if (!p) return { json: { skipped: true } };
  const res = item.json || {};
  const message = res.message || {};
  return {
    json: Object.assign({}, p, {
      status: 'followup_drafted',
      sequence_state: 'active',
      draft_id: String(res.id || p.draft_id || ''),
      gmail_thread_id: String(message.threadId || p.gmail_thread_id || ''),
      followups_drafted: p.followups_drafted_next,
      draft_created_at: new Date().toISOString(),
    }),
  };
});
